import pytest


class BadInput(Exception):
    def __init__(self, text: str) -> None:
        self.text = text


def sum_parsed(xs: list[str]) -> int:
    """Parse every string as an integer and return their sum.

    Raises BadInput on the first string that cannot be parsed as an integer.
    """
    total = 0
    for s in xs:
        try:
            total += int(s)
        except ValueError:
            raise BadInput(s) from None
    return total


def test_sum_parsed_empty() -> None:
    assert sum_parsed([]) == 0


def test_sum_parsed_valid() -> None:
    assert sum_parsed(["1", "2", "3"]) == 6
    assert sum_parsed(["-5", "10", "0"]) == 5


def test_sum_parsed_invalid_raises_bad_input() -> None:
    with pytest.raises(BadInput) as exc_info:
        sum_parsed(["1", "abc", "3"])
    assert exc_info.value.text == "abc"


def test_sum_parsed_stops_at_first_invalid() -> None:
    with pytest.raises(BadInput) as exc_info:
        sum_parsed(["10", "invalid1", "invalid2"])
    assert exc_info.value.text == "invalid1"


def test_sum_parsed_float_string_is_invalid() -> None:
    with pytest.raises(BadInput) as exc_info:
        sum_parsed(["3.14"])
    assert exc_info.value.text == "3.14"

